mapper.update:
UPDATE ref_data
SET parent_id = #{parentId},
    sort_order = #{sortOrder},
    status = #{status},
    field_data = #{fieldData}
WHERE id = #{id}

mapper.select:
SELECT * FROM ref_data

    ref_type = #{refType}

        AND parent_id = #{parentId}


        AND parent_id IS NULL


        AND status = #{status}


        AND JSON_SEARCH(field_data, 'one', CONCAT('%', #{keyword}, '%')) IS NOT NULL


ORDER BY sort_order ASC, id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM ref_data

    ref_type = #{refType}

        AND parent_id = #{parentId}


        AND parent_id IS NULL


        AND status = #{status}


        AND JSON_SEARCH(field_data, 'one', CONCAT('%', #{keyword}, '%')) IS NOT NULL

SELECT COALESCE(MAX(sort_order), 0) FROM ref_data
WHERE ref_type = #{refType}
AND parent_id = #{parentId}
AND parent_id IS NULL
